"""Generate the academic SQL Server dictionary directly from the checked-in DDL."""
import re
from pathlib import Path

root = Path(__file__).resolve().parent
schema = (root / "001_schema.sql").read_text(encoding="utf-8-sig")
tables = re.findall(r"CREATE TABLE dbo\.(\w+) \((.*?)\);", schema, re.S)
if len(tables) != 22:
    raise ValueError("Schema parser expected exactly 22 tables; inspect changed DDL")
lines = [
    "# SQL Server data dictionary", "",
    "Generated by `document_schema.py` from `001_schema.sql`. This is the active SQL Server implementation; the parent directory's dictionary is preserved MySQL reference material.", "",
    "All 22 tables are in dbo. Text uses NVARCHAR, timestamps use DATETIME2(3) with UTC by convention, flags use BIT, and event ordering keys use BIGINT IDENTITY. SQL Server does not attach a time zone to DATETIME2. Foreign keys use NO ACTION unless explicitly declared otherwise. Keys, nullability and CHECK conditions below are copied from the authoritative DDL.", "",
    "Evidence has exactly one source; three filtered unique indexes allow many NULLs while preventing duplicate non-NULL source references. Audit rows have exactly one case/review target. ISJSON validates stored audit snapshots; it does not enforce business semantics.", "",
]
for name, body in tables:
    indexes = re.findall(rf"CREATE (?:UNIQUE )?INDEX [^;]+ ON dbo\.{name}\([^;]+;", schema)
    lines.extend([f"## {name}", "", "```sql", f"CREATE TABLE dbo.{name} ({body});", *indexes, "```", ""])
lines.extend([
    "## Relationships and normalization", "",
    "The [ER diagram](../ER.md) describes the same 22 entities and foreign-key relationships. Its varchar labels reflect the preserved MySQL source; use the NVARCHAR/DATETIME2 definitions above for SQL Server. Optional evidence source links are mutually exclusive, not three mandatory parents.", "",
    "See [normalization](../NORMALIZATION.md) for 1NF, 2NF, 3NF, junction tables, immutable finding-run references, provenance and intentional historical JSON snapshots. API case/metadata/note operations now add audit entries as well as the original review/status procedures. Direct DML outside these paths is not automatically audited.", "",
])
(root / "DATA-DICTIONARY.md").write_text("\n".join(lines), encoding="utf-8")
print(f"Documented {len(tables)} SQL Server tables")
